export function generateNationalWave2() {
  if (pages.length !== 100) throw new Error(`Expected 100 pages, found ${pages.length}.`);
  if (new Set(pages.map((page) => page.slug)).size !== pages.length) throw new Error("Duplicate wave-two slug.");
  for (const page of pages) writeFileSync(resolve(root, page.slug), render(page), "utf8");
  const rolloutPath = resolve(root, "national-seo-rollout.json");
  const rollout = JSON.parse(readFileSync(rolloutPath, "utf8"));
  if (!rollout.completedBatches.includes(1)) throw new Error("Batch one is not recorded as complete.");
  rollout.completedBatches = [...new Set([...rollout.completedBatches, 2])].sort((left, right) => left - right);
  rollout.updated = contentDate;
  rollout.publishedPages = rollout.completedBatches.length * rollout.pagesPerDay;
  rollout.remainingPages = rollout.targetPages - rollout.publishedPages;
  rollout.nextBatch = 3;
  writeFileSync(rolloutPath, `${JSON.stringify(rollout, null, 2)}\n`, "utf8");
  console.log(`Generated ${pages.length} original national guide pages for batch 2.`);
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) generateNationalWave2();
